-- https://github.com/ClickHouse/ClickHouse/issues/133337
SELECT toTypeName(x), x, x = true FROM (SELECT true AS x UNION ALL SELECT toUInt8(2) AS x) ORDER BY x;
SELECT toTypeName(x), x, x = true FROM (SELECT toUInt8(2) AS x UNION ALL SELECT true AS x) ORDER BY x;
SELECT toTypeName(x), x FROM (SELECT true AS x UNION ALL SELECT false AS x) ORDER BY x;
SELECT toTypeName(x), x FROM (SELECT [true] AS x UNION ALL SELECT [toUInt8(2)]) ORDER BY x;
SELECT toTypeName(x), x FROM (SELECT CAST(true, 'Nullable(Bool)') AS x UNION ALL SELECT toUInt8(2)) ORDER BY x;
SELECT toTypeName(x), x FROM (SELECT tuple(true) AS x UNION ALL SELECT tuple(toUInt8(2))) ORDER BY x;
SELECT toTypeName(x), x FROM (SELECT map('a', true) AS x UNION ALL SELECT map('a', toUInt8(2))) ORDER BY toString(x);
SELECT toTypeName(x), x FROM (SELECT toLowCardinality(true) AS x UNION ALL SELECT toLowCardinality(toUInt8(2))) ORDER BY x;
SELECT toTypeName(x), x FROM (SELECT true AS x INTERSECT SELECT toUInt8(1));
SELECT toTypeName(if(number = 0, true, toUInt8(2))), if(number = 0, true, toUInt8(2)) FROM numbers(2);
SELECT toTypeName(if(number = 1, toUInt8(2), true)), if(number = 1, toUInt8(2), true) FROM numbers(2);
SELECT toTypeName(if(number = 0, true, false)), toTypeName(multiIf(number = 0, true, toUInt8(2))), toTypeName(coalesce(CAST(number, 'Nullable(Bool)'), toUInt8(2))) FROM numbers(1);
SELECT [true, 2], toTypeName([true, 2]), [2, true], toTypeName([2, true]), [true, false], toTypeName([true, false]);
SELECT toTypeName(v), v FROM (SELECT true AS v) a FULL JOIN (SELECT toUInt8(2) AS v) b USING v ORDER BY v;
SELECT toTypeName(v), v FROM (SELECT toUInt8(2) AS v) a FULL JOIN (SELECT true AS v) b USING v ORDER BY v;
SELECT toTypeName(a.v), toTypeName(b.v), toTypeName(v) FROM (SELECT true AS v) a INNER JOIN (SELECT toUInt8(1) AS v) b USING v;
WITH RECURSIVE r AS (SELECT true AS x UNION ALL SELECT toUInt8(x + 1) FROM r WHERE x < 2) SELECT toTypeName(x), x FROM r ORDER BY x;
SELECT toTypeName(x), x FROM (SELECT '{"a" : true}'::JSON(a Bool) AS x UNION ALL SELECT '{"a" : 2}'::JSON(a UInt8)) ORDER BY toString(x);
SELECT toTypeName(x), x FROM (SELECT '{"a" : 2}'::JSON(a UInt8) AS x UNION ALL SELECT '{"a" : true}'::JSON(a Bool)) ORDER BY toString(x);
CREATE TABLE t_saf (s SimpleAggregateFunction(any, Bool), b Bool, u UInt8) ENGINE = Memory;
INSERT INTO t_saf VALUES (true, true, 2);
SELECT toTypeName(x), x FROM (SELECT s AS x FROM t_saf UNION ALL SELECT u FROM t_saf) ORDER BY x;
SELECT toTypeName(x), x FROM (SELECT u AS x FROM t_saf UNION ALL SELECT s FROM t_saf) ORDER BY x;
SELECT toTypeName(x) FROM (SELECT s AS x FROM t_saf UNION ALL SELECT b FROM t_saf);
DROP TABLE t_saf;
SELECT a.*, toTypeName(a.*) FROM (SELECT true AS v) a INNER JOIN (SELECT toUInt8(1) AS v) b USING v;
CREATE TABLE t_alias_key (x UInt8, k Bool ALIAS x > 0) ENGINE = Memory;
INSERT INTO t_alias_key VALUES (1);
SELECT toTypeName(k), k FROM t_alias_key FULL JOIN (SELECT toUInt8(2) AS k) b USING k ORDER BY k;
DROP TABLE t_alias_key;
SELECT toTypeName(s), finalizeAggregation(s) AS v, v = true FROM (SELECT anyState(true) AS s UNION ALL SELECT anyState(toUInt8(2))) ORDER BY v;
SELECT toTypeName(s), finalizeAggregation(s) AS v, v = true FROM (SELECT anyState(toUInt8(2)) AS s UNION ALL SELECT anyState(true)) ORDER BY v;
SELECT toTypeName(s) FROM (SELECT anyState(true) AS s UNION ALL SELECT anyState(false));
SELECT toTypeName([anyState(true), anyState(toUInt8(2))]), toTypeName([anyState(toUInt8(2)), anyState(true)]);
SELECT toTypeName([argMaxState(true, 1), argMaxState(toUInt8(2), 2)]), toTypeName([argMaxState(toUInt8(2), 2), argMaxState(true, 1)]);
SELECT toTypeName(s), finalizeAggregation(s) AS v FROM (SELECT anyTupleState(tuple(true)) AS s UNION ALL SELECT anyTupleState(tuple(toUInt8(2)))) ORDER BY v;
SELECT toTypeName(s), finalizeAggregation(s) AS v FROM (SELECT anyTupleState(tuple(toUInt8(2))) AS s UNION ALL SELECT anyTupleState(tuple(true))) ORDER BY v;
SELECT toTypeName([anyTupleState(tuple(true)), anyTupleState(tuple(toUInt8(2)))]), toTypeName([anyTupleState(tuple(toUInt8(2))), anyTupleState(tuple(true))]);
SELECT notEmpty(if(number = 0, ['{"a":[true]}'::JSON(a Variant(Array(Bool), String))], ['{"a":[2]}'::JSON(a Variant(Array(UInt8), String))])) FROM numbers(2) SETTINGS use_variant_as_common_type = 1, short_circuit_function_evaluation = 'disable';
SELECT notEmpty(if(number = 1, ['{"a":[2]}'::JSON(a Variant(Array(UInt8), String))], ['{"a":[true]}'::JSON(a Variant(Array(Bool), String))])) FROM numbers(2) SETTINGS use_variant_as_common_type = 1, short_circuit_function_evaluation = 'disable';
SELECT toUInt8(x.1), toUInt8(x.2) FROM (SELECT anySimpleState(tuple(true, toUInt8(0), [true]::Variant(Array(Bool), String))) AS x UNION ALL SELECT anySimpleState(tuple(toUInt8(0), true, [toUInt8(2)]::Variant(Array(UInt8), String)))) ORDER BY ALL;
SELECT toUInt8(x.1), toUInt8(x.2) FROM (SELECT anySimpleState(tuple(toUInt8(0), true, [toUInt8(2)]::Variant(Array(UInt8), String))) AS x UNION ALL SELECT anySimpleState(tuple(true, toUInt8(0), [true]::Variant(Array(Bool), String)))) ORDER BY ALL;
SELECT toUInt8(x.1), toUInt8(x.2) FROM (SELECT toNullable(anySimpleState(tuple(true, toUInt8(0), [true]::Variant(Array(Bool), String)))) AS x UNION ALL SELECT toNullable(anySimpleState(tuple(toUInt8(0), true, [toUInt8(2)]::Variant(Array(UInt8), String))))) ORDER BY ALL;
SELECT toUInt8(x.1), toUInt8(x.2) FROM (SELECT toNullable(anySimpleState(tuple(toUInt8(0), true, [toUInt8(2)]::Variant(Array(UInt8), String)))) AS x UNION ALL SELECT toNullable(anySimpleState(tuple(true, toUInt8(0), [true]::Variant(Array(Bool), String))))) ORDER BY ALL;
SELECT toUInt8(k.1), toUInt8(k.2) FROM (SELECT anySimpleState(tuple(true, toUInt8(0), [true]::Variant(Array(Bool), String))) AS k) a FULL JOIN (SELECT anySimpleState(tuple(toUInt8(0), true, [toUInt8(2)]::Variant(Array(UInt8), String))) AS k) b USING k ORDER BY ALL;
SELECT toUInt8(k.1), toUInt8(k.2) FROM (SELECT anySimpleState(tuple(toUInt8(0), true, [toUInt8(2)]::Variant(Array(UInt8), String))) AS k) a FULL JOIN (SELECT anySimpleState(tuple(true, toUInt8(0), [true]::Variant(Array(Bool), String))) AS k) b USING k ORDER BY ALL;
SELECT toTypeName(x.1), x.1 FROM (SELECT tuple(true, [true]::Variant(Array(Bool), String)) AS x UNION ALL SELECT tuple(toUInt8(2), [toUInt8(2)]::Variant(Array(UInt8), String))) ORDER BY x.1;
SELECT toTypeName(x.1), x.1 FROM (SELECT tuple(toUInt8(2), [toUInt8(2)]::Variant(Array(UInt8), String)) AS x UNION ALL SELECT tuple(true, [true]::Variant(Array(Bool), String))) ORDER BY x.1;
SELECT toTypeName(x.1), x.1 FROM (SELECT anySimpleState(tuple(true, toUInt8(7)::Variant(UInt8, String))) AS x UNION ALL SELECT tuple(toUInt8(2), toUInt8(7)::Variant(UInt8, String))) ORDER BY x.1;
SELECT toTypeName(x.1), x.1 FROM (SELECT tuple(toUInt8(2), toUInt8(7)::Variant(UInt8, String)) AS x UNION ALL SELECT anySimpleState(tuple(true, toUInt8(7)::Variant(UInt8, String)))) ORDER BY x.1;
SELECT k, toTypeName(k) FROM (SELECT CAST(number + 2 AS SimpleAggregateFunction(groupBitOr, Bool)) AS k FROM numbers(1)) a FULL JOIN (SELECT toUInt16(number) AS k FROM numbers(1)) b USING k ORDER BY k SETTINGS join_use_nulls = 0;
SELECT k, toTypeName(k) FROM (SELECT toUInt16(number) AS k FROM numbers(1)) a FULL JOIN (SELECT CAST(number + 2 AS SimpleAggregateFunction(groupBitOr, Bool)) AS k FROM numbers(1)) b USING k ORDER BY k SETTINGS join_use_nulls = 0;
SELECT toTypeName(x), x, x = true FROM (SELECT ifNull(CAST(NULL, 'Nullable(Bool)'), toUInt8(2)) AS x);
SELECT toTypeName(x), x, x = true FROM (SELECT ifNull(CAST(NULL, 'Nullable(UInt8)'), true) AS x);
